export function formatTranslation(text, params = {}) {
  if (!text) return "";
  return Object.entries(params).reduce((acc, [key, value]) => {
    return acc.replace(new RegExp(`\\{\\s*${key}\\s*\\}`, "g"), String(value));
  }, text);
}

export function toBhashiniLocale(lang) {
  const map = {
    en: "en-IN",
    hi: "hi-IN",
    bn: "bn-IN",
    te: "te-IN",
    mr: "mr-IN",
    ta: "ta-IN"
  };
  return map[lang] || "en-IN";
}

export function fromBhashiniLocale(locale) {
  if (!locale) return "en";
  const prefix = locale.split("-")[0].toLowerCase();
  const supported = ["en", "hi", "bn", "te", "mr", "ta"];
  return supported.includes(prefix) ? prefix : "en";
}
